{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "Two independent authors (A.B. and G.P.) completed reference screening and study selection using the following predefined inclusion criteria: (1) population : children, young people, or adults who have experienced a suspected hemorrhage or TBI following a traumatic incident; (2) intervention : administration of a systemic hemostatic agent, (e.g., rFVIIa, TXA, fibrinogen concentrate, prothrombin complex concentrate, or another anti-fibrinolytic agent); (3) comparison : no treatment, placebo, standard care (e.g., crystalloids, blood components), or any other hemostatic agent; and (iv) setting: systemic hemostatic treatment initiated in the prehospital setting. Only RCTs were considered eligible for inclusion; case reports, editorials, and letters were excluded from the search.",
      "reason": "The manuscript explicitly defines the population, intervention, comparison, setting, and study design (RCTs) used to determine eligibility."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not specify eligibility criteria regarding language or publication year restrictions."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not distinguish between exclusion due to outcomes not being measured versus outcomes not being reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_10",
      "quote": "Subgroup analyses were planned for (1) type of population (e.g., subjects with significant hemorrhage and subjects with TBI); (2) type of injury (e.g., blunt trauma, penetrating trauma); and (3) doses of systemic hemostatic agent when available.",
      "reason": "The manuscript specifies the groups used for synthesis (subgroup analyses) linked to the review's objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_21",
      "quote": "Fourth, inclusion criteria were narrow, aiming to balance pros and cons. We considered eligible all RCTs that investigated several interventions delivered in any setting (civilian and military). Thus, although we were able to offer the highest level of evidence (RCTs with high certainty of evidence) achieving more consistency in the interpretation of findings, this approach limited the results",
      "reason": "The authors provide a rationale for the restriction to RCTs, explaining that it was intended to balance pros and cons and achieve consistency in findings."
    }
  ],
  "confidence": 100
}

